            nearFieldSupportScale: farAggregateNearFieldSupportScale,
            openingTheta: farAggregateOpeningTheta,
            publicEpochIdentity:
              twoLevelPostMechanicsEpoch.transaction.epochIdentity,
            gravitationalConstant: farAggregateGravitationalConstant,
