        ownsStateBuffer: false,
        ownsThermoBuffer: false,
        phaseCarrierPlan:
          twoLevelPostMechanicsClosure.phaseCarrierPlan
          ?? twoLevelPublicEpochUploads.sphParticleUpload.phaseCarrierPlan
